// A scoped slot's body is built by the inline path, as the rest of a .pdx is (#364).
//
// It was the one part still generated by the template path: an html`` tagged template core parsed
// at runtime, which put an HTML comment in the DOM and evaluated `${…}` in an unbound attribute,
// where every other part of the same template shows the text as written. Here a child declares a
// scoped slot outlet, a parent fills it, and both are compiled as a build compiles them.
import { describe, it, expect } from 'vitest';
import * as core from '../src/index';
import { compile } from '../../compiler/src/plugin';

const settle = async () => {
    for (let i = 0; i < 3; i++) {
        await new Promise((r) => setTimeout(r, 0));
        await new Promise((r) => requestAnimationFrame(() => r(null)));
    }
};

/** Compile a .pdx as a production build does and define its component on this core. */
function define(name: string, template: string, script = ''): string {
    const src = `<template>${template}</template>\n<script>\n${script}\n</script>\n`;
    const { code } = compile(src, `${name}.pdx`, [], undefined, { production: true });
    const body = code.replace(/^\s*import\s*\{([^}]*)\}\s*from\s*'@pdxui\/core';?\s*$/gm, 'const {$1} = __core;');
    new Function('__core', body)(core);
    return code;
}

describe('a scoped slot fill', () => {
    define('app-slot-owner',
        '<p class="own"><slot name="cell" :row="r">none</slot></p><button @click="r = r + 1">next</button>',
        'let r = $signal(1);');
    const parent = define('app-slot-filler',
        '<app-slot-owner><slot name="cell" let:row><!-- a note --><b title="${row}">row {{ row }}</b></slot></app-slot-owner>');

    it('is compiled without the template path: no html`` in the module', () => {
        expect(parent).toContain('slotCarrier(');
        expect(parent, 'the slot body is still an html`` template').not.toMatch(/\bhtml`/);
    });

    it('renders with its scope values, and follows them', async () => {
        const el = document.createElement('app-slot-filler');
        document.body.appendChild(el);
        await settle();
        const b = () => el.querySelector('.own b');
        expect(b()?.textContent).toBe('row 1');
        (el.querySelector('app-slot-owner button') as HTMLButtonElement).click();
        await settle();
        expect(b()?.textContent, 'a changed scope value did not reach the slot').toBe('row 2');
    });

    it('reads `${…}` in an unbound attribute and an HTML comment as everywhere else', async () => {
        const el = document.createElement('app-slot-filler');
        document.body.appendChild(el);
        await settle();
        expect(el.querySelector('.own b')?.getAttribute('title'), '`${row}` was evaluated').toBe('${row}');
        const comments: string[] = [];
        const walker = document.createTreeWalker(el.querySelector('.own')!, NodeFilter.SHOW_COMMENT);
        while (walker.nextNode()) comments.push((walker.currentNode as Comment).data);
        expect(comments.filter((c) => c.includes('a note')), 'the HTML comment was put in the DOM').toEqual([]);
    });
});
